function groupUomFactor(type,part,sub,uom){const items=active(rows('items')).filter(i=>i.Product_Type===type&&i.PART===part&&i.SUB_PART===sub),codes=new Set(items.map(i=>i.Item_Code)),factors=new Set(rows('itemUoms').filter(x=>codes.has(x.Item_Code)&&x.UOM===uom&&String(x.Active||'Y').toUpperCase()!=='N').map(x=>Number(x.KG_Per_UOM)).filter(x=>x>0));for(const i of items)if((i.Base_UOM||'MT')===uom)factors.add(Number(i.KG_Per_UOM||1000));if(uom==='KG')factors.add(1);if(uom==='MT')factors.add(1000);return factors.size===1?[...factors][0]:0}
function excelDateIso(v){if(v instanceof Date&&!Number.isNaN(v.getTime()))return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;if(typeof v==='number'&&typeof XLSX!=='undefined'&&XLSX){const d=XLSX.SSF.parse_date_code(v);return d?`${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`:''}const x=String(v||'').trim();if(/^\d{4}-\d{2}-\d{2}$/.test(x))return x;const m=x.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);return m?`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`:normDate(x)}
