async function saveWeeklyBatch(){try{const week=$('#wWeek').value,els=[...document.querySelectorAll('[data-week-row]')];if(!els.length)throw Error('เพิ่มรายการ Plan อย่างน้อย 1 รายการ');const objects=els.map(el=>{const u=el.querySelector('[data-w-uom]').selectedOptions[0];return buildWeeklyRecord(week,null,{Sale_ID:el.querySelector('[data-w-sale]').value,Plan_Date:el.querySelector('[data-w-date]').value,Customer_Code:el.querySelector('[data-w-customer]').value,Product_Type:el.querySelector('[data-w-product-type]').value,PART:el.querySelector('[data-w-part]').value,SUB_PART:el.querySelector('[data-w-subpart]').value,Plan_Qty:el.querySelector('[data-w-qty]').value,Plan_UOM:u?.value,KG_Per_UOM:u?.dataset.kg,Plan_Type:el.querySelector('[data-w-type]').value,Plan_ID:el.dataset.planId,Version:rows('weeklyPlans').find(x=>x.Plan_ID===el.dataset.planId)?.Version,_row:el.dataset.sheetRow})});const newRows=[];for(const o of objects){if(o._row){const old=rows('weeklyPlans').find(x=>x.Plan_ID===o.Plan_ID);o.Version=Number(old?.Version||0)+1;await updateRow(TAB.weeklyPlans,o._row,o)}else newRows.push(o)}if(newRows.length)await append(TAB.weeklyPlans,newRows);closeModal();ping(`บันทึกแผน ${week} จำนวน ${objects.length} รายการ`);await loadDb()}catch(e){ping(e.message,true)}}
