function buildFollowupRecords(sale,type,part,sub,entries,batch=id('BATCH')){if(!sale||!type||!part||!sub)throw Error('เลือกพนักงาน Product Type, PART และ SUB-PART ให้ครบ');if(!entries.length)throw Error('เพิ่มรายการ Plan อย่างน้อย 1 รายการ');return entries.map(e=>{const isProspect=e.Customer_Type==='PROSPECT',customer=isProspect?null:rows('customers').find(c=>c.Customer_Code===e.Customer_Code),qty=Number(e.Plan_Qty),kg=Number(e.KG_Per_UOM),due=normDate(e.Due_Date);if(!(qty>0)||!due||!e.Action_Type||!e.Plan_UOM||!(kg>0)||(!isProspect&&!customer)||(isProspect&&!String(e.Prospect_Name||'').trim()))throw Error('กรอกรายละเอียด Plan ให้ครบทุกแถว');if(e.Item_Code){const item=rows('items').find(i=>i.Item_Code===e.Item_Code);if(!item||item.Product_Type!==type||item.PART!==part||item.SUB_PART!==sub)throw Error('สินค้าในรายการไม่ตรงกับกลุ่มสินค้าที่เลือก')}return {Action_ID:id('ACT'),Created_Date:localToday(),Due_Date:due,Sale_ID:sale.Sale_ID,Customer_Code:customer?.Customer_Code||'',Item_Code:'',Action_Type:e.Action_Type,Expected_Qty_MT:qty*kg/1000,Status:'OPEN',Result:e.Action_Detail||'',Next_Action:'',Data_Status:'LIVE',Channel:sale.Channel||sale.Team||'',Plan_MT:qty*kg/1000,Closed_Sales_MT:0,Parent_Action_ID:'',Is_Deleted:'N',Manager_Comment:'',Updated_By:me,Updated_At:new Date().toISOString(),Plan_Qty:qty,Plan_UOM:e.Plan_UOM,KG_Per_UOM:kg,Plan_KG:qty*kg,Closed_Sales_Qty:0,Closed_Sales_UOM:e.Plan_UOM,Prospect_ID:'',Prospect_Name:isProspect?String(e.Prospect_Name).trim():'',Batch_ID:batch,Product_Type:type,PART:part,SUB_PART:sub,Next_Action_Date:''}})}
async function saveActionBatch(){try{const sale=rows('sales').find(s=>s.Sale_ID===$('#baSale').value),type=$('#baType').value,part=$('#baPart').value,sub=$('#baSub').value,els=[...document.querySelectorAll('[data-action-plan]')],batch=id('BATCH'),entries=els.map(el=>{const u=el.querySelector('[data-a-uom]').selectedOptions[0];return {Due_Date:el.querySelector('[data-a-date]').value,Action_Type:el.querySelector('[data-a-kind]').value,Customer_Type:el.querySelector('[data-a-customer-type]').value,Customer_Code:el.querySelector('[data-a-customer]').value,Prospect_Name:el.querySelector('[data-a-prospect]').value,Plan_Qty:el.querySelector('[data-a-qty]').value,Plan_UOM:u?.value,KG_Per_UOM:u?.dataset.kg,Action_Detail:el.querySelector('[data-a-detail]').value}}),objects=buildFollowupRecords(sale,type,part,sub,entries,batch);await append(TAB.actions,objects);await append(TAB.actionHistory,objects.map(o=>({History_ID:id('HIS'),Action_ID:o.Action_ID,Changed_At:new Date().toISOString(),Changed_By:me,Event_Type:'CREATE',New_Status:o.Status,New_Due_Date:o.Due_Date,New_Plan_MT:o.Plan_MT,New_Next_Action:o.Next_Action})));closeModal();ping(`บันทึก Action ${objects.length} รายการแล้ว`);await loadDb()}catch(e){ping(e.message,true)}}
