async function importMaster(file){if(!file)return;try{const wb=XLSX.read(await file.arrayBuffer()),tab=TAB[mtab],sheet=wb.Sheets[tab]||wb.Sheets[wb.SheetNames[0]],data=XLSX.utils.sheet_to_json(sheet,{defval:''});if(!data.length)throw Error(`ไม่พบข้อมูลในชีต ${tab}`);const headers=dbHeaders[tab]||Object.keys(data[0]),key=headers[0],existing=rows(mtab),index=new Map(existing.map(x=>[String(x[key]),x])),adds=[],updates=[];for(const src of data){const code=String(src[key]??'').trim();if(!code)continue;const found=index.get(code);if(found){const merged={...found};for(const h of headers)if(src[h]!==undefined&&src[h]!=='')merged[h]=src[h];updates.push([found._row,merged])}else adds.push(Object.fromEntries(headers.map(h=>[h,src[h]??''])))}for(const [r,o] of updates)await updateRow(tab,r,o);if(adds.length)await append(tab,adds);ping(`นำเข้าข้อมูลแล้ว · เพิ่ม ${adds.length} · ปรับปรุง ${updates.length}`);await loadDb()}catch(e){ping(e.message,true)}}
