 if(mtab==='items'&&key==='Base_UOM')return `<input data-master-key="${esc(key)}" value="${esc(value||'KG')}" placeholder="KG"><small>หน่วยฐานของ Item; ตัวคูณหน่วยอื่นตั้งใน “หน่วยและ Conversion”</small>`;
