async function importMaster(file){
 if(!file)return;
 try{
  const wb=XLSX.read(await file.arrayBuffer()),tab=TAB[mtab],sheet=wb.Sheets[tab]||wb.Sheets[wb.SheetNames[0]],data=XLSX.utils.sheet_to_json(sheet,{defval:''});
  if(!data.length)throw Error(`ไม่พบข้อมูลในชีต ${tab}`);
  const headers=dbHeaders[tab]||HEAD[tab]||Object.keys(data[0]),natural={groupProducts:'Group_Product_Name',productTypes:'Product_Type',parts:'PART',subParts:null,items:'Item_Code',itemUoms:null,customerProducts:null,prospects:null}[mtab],key=natural||headers[0],existing=rows(mtab),keyOf=o=>mtab==='itemUoms'?`${o.Item_Code}|${String(o.UOM||'').toLowerCase()}`:mtab==='groupProducts'?String(o.Group_Product_Name||'').trim().toLowerCase():mtab==='subParts'?`${o.PART_ID}|${String(o.SUB_PART||'').trim().toLowerCase()}`:mtab==='customerProducts'?`${o.Customer_Code}|${o.Product_Type}|${o.PART}|${o.SUB_PART}`:mtab==='prospects'?`${o.Prospect_Name}|${o.Channel}|${o.Owner_Sale_ID}|${o.Product_Type}|${o.PART}|${o.SUB_PART}`:String(o[key]??''),index=new Map(existing.map(x=>[keyOf(x),x])),adds=[],updates=[],seen=new Set();
  for(const src of data){let obj=Object.fromEntries(headers.map(h=>[h,src[h]??'']));if(!keyOf(obj).replace('|','').trim())continue;if(seen.has(keyOf(obj)))throw Error(`พบ Item Code/UOM ซ้ำในไฟล์: ${keyOf(obj)}`);seen.add(keyOf(obj));
   const generatedIdField={groupProducts:'Group_Product_ID',productTypes:'Product_Type_ID',parts:'PART_ID',subParts:'SUB_PART_ID',customerProducts:'Association_ID',prospects:'Prospect_ID'}[mtab];if(generatedIdField&&!obj[generatedIdField])obj[generatedIdField]=id(({groupProducts:'GPR',productTypes:'PTY',parts:'PRT',subParts:'SUB',customerProducts:'CPL',prospects:'PRO'}[mtab]));
   if(mtab==='subParts'&&!String(obj.SUB_PART||'').trim())throw Error('กรุณาระบุ SUB-PART');if(mtab==='subParts'&&!rows('parts').some(x=>String(x.PART_ID)===String(obj.PART_ID)&&String(x.Active||'Y').toUpperCase()!=='N'))throw Error(`SUB-PART ${obj.SUB_PART||''}: PART_ID ไม่พบใน Master PART`);if(mtab==='groupProducts'){const type=rows('productTypes').find(x=>String(x.Product_Type_ID)===String(obj.Product_Type_ID)),part=rows('parts').find(x=>String(x.PART_ID)===String(obj.PART_ID)),sub=rows('subParts').find(x=>String(x.SUB_PART_ID)===String(obj.SUB_PART_ID)&&String(x.PART_ID)===String(obj.PART_ID));if(!type||!part||!sub)throw Error(`Group Product ${obj.Group_Product_Name||''}: ต้องอ้าง Product_Type_ID, PART_ID และ SUB_PART_ID ที่มีอยู่ และ SUB_PART ต้องอยู่ใต้ PART`)}if(mtab==='items'){if(obj.Group_Product_ID){const gp=rows('groupProducts').find(x=>String(x.Group_Product_ID)===String(obj.Group_Product_ID));if(!gp)throw Error(`Item ${obj.Item_Code}: Group_Product_ID ไม่พบใน Master`);const pId=rows('parts').find(p=>String(p.PART)===String(obj.PART))?.PART_ID,tId=rows('productTypes').find(t=>String(t.Product_Type)===String(obj.Product_Type))?.Product_Type_ID,sId=rows('subParts').find(x=>String(x.SUB_PART)===String(obj.SUB_PART)&&String(x.PART_ID)===String(pId))?.SUB_PART_ID;if(String(gp.Product_Type_ID)!==String(tId)||String(gp.PART_ID)!==String(pId)||String(gp.SUB_PART_ID)!==String(sId))throw Error(`Item ${obj.Item_Code}: Group Product ไม่ตรงกับ Product Type / PART / SUB_PART`);}for(const f of ['Product_Type','PART','SUB_PART'])if(!active(rows(({Product_Type:'productTypes',PART:'parts',SUB_PART:'subParts'}[f]))).some(x=>String(x[f])===String(obj[f])))throw Error(`Item ${obj.Item_Code}: ${f} ไม่พบใน Master`);obj.Product_Type_ID=rows('productTypes').find(x=>String(x.Product_Type)===String(obj.Product_Type))?.Product_Type_ID||'';obj.PART_ID=rows('parts').find(x=>String(x.PART)===String(obj.PART))?.PART_ID||'';const sub=rows('subParts').find(x=>String(x.SUB_PART)===String(obj.SUB_PART)&&String(x.PART_ID)===String(obj.PART_ID));if(!sub)throw Error(`Item ${obj.Item_Code}: SUB_PART ไม่ได้อยู่ภายใต้ PART ${obj.PART}`);obj.SUB_PART_ID=sub.SUB_PART_ID||'';if(!obj.Base_UOM)obj.Base_UOM='KG';if(!obj.KG_Per_UOM)obj.KG_Per_UOM=obj.Base_UOM==='KG'?1:1000}
   if(mtab==='itemUoms'){if(!rows('items').some(x=>String(x.Item_Code)===String(obj.Item_Code)))throw Error(`Item Code ${obj.Item_Code} ไม่พบ`);if(!(Number(obj.KG_Per_UOM)>0))throw Error(`Conversion ของ ${obj.Item_Code}/${obj.UOM} ต้องมากกว่า 0`)}
   const found=index.get(keyOf(obj));if(found){const idField=generatedIdField;if(idField&&!String(src[idField]||'').trim())obj[idField]=found[idField];updates.push([found._row,{...found,...obj}])}else adds.push(obj)
  }
  for(const [row,obj] of updates)await updateRow(tab,row,obj);if(adds.length)await append(tab,adds);ping(`นำเข้าแล้ว · เพิ่ม ${adds.length} · ปรับปรุง ${updates.length}`);await loadDb()
 }catch(e){ping(e.message,true)}
}


function actualUomConversion(item,uom){const matches=rows('itemUoms').filter(x=>String(x.Item_Code)===String(item?.Item_Code)&&String(x.UOM).toLowerCase()===String(uom||'').toLowerCase()&&String(x.Active||'Y').toUpperCase()!=='N');if(matches.length>1)return {factor:0,error:'Item/UOM ซ้ำใน M_ITEM_UOM'};if(matches.length===1){const factor=Number(matches[0].KG_Per_UOM);return factor>0?{factor,error:''}:{factor:0,error:'Conversion KG_Per_UOM ไม่ถูกต้อง'}}if(String(item?.Base_UOM||'').toLowerCase()===String(uom||'').toLowerCase()){const factor=Number(item?.KG_Per_UOM||1);return factor>0?{factor,error:''}:{factor:0,error:'Conversion KG_Per_UOM ไม่ถูกต้อง'}}return {factor:0,error:'UOM ไม่พบสำหรับ Item Code ใน M_ITEM_UOM'}}
